svg.script:
(function () {
  var svg = document.documentElement;
  var slot = svg.querySelector('[data-reaction-slot]');
  var image = svg.querySelector('[data-reaction-image]');
  if (!slot || !image) return;

  function clean(value) { return (value || '').trim(); }
  function slugify(value) {
    return clean(value)
      .normalize('NFKD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .replace(/['’]/g, '')
      .replace(/[^a-z0-9]+/g, '_')
      .replace(/^_+|_+$/g, '');
  }
  function clearReaction() {
    image.removeAttribute('href');
    image.removeAttributeNS('http://www.w3.org/1999/xlink', 'href');
    image.setAttribute('visibility', 'hidden');
    image.removeAttribute('aria-label');
    slot.setAttribute('data-reaction-state', 'empty');
    slot.removeAttribute('data-reaction-action');
  }
  function showReaction(source, action) {
    if (!source) return clearReaction();
    slot.setAttribute('data-reaction-state', 'loading');
    if (action) slot.setAttribute('data-reaction-action', action);
    image.setAttribute('href', source);
    image.setAttribute('aria-label', action ? action + ' reaction' : 'NPC reaction');
    image.setAttribute('visibility', 'visible');
  }
  image.addEventListener('load', function () {
    if (image.getAttribute('href')) slot.setAttribute('data-reaction-state', 'filled');
  });
  image.addEventListener('error', clearReaction);

  var params;
  try { params = new URLSearchParams(window.location.search); }
  catch (_) { clearReaction(); return; }
  var direct = clean(params.get('reaction'));
  var action = clean(params.get('npcAction') || params.get('action'));
  var base = clean(params.get('reactionBase')) || '../reactions/';
  if (direct) {
    showReaction(direct, action);
  } else if (action) {
    showReaction(base.replace(/\/?$/, '/') + slugify(action) + '.svg', action);
  } else {
    clearReaction();
  }

  svg.setReaction = function (source, actionLabel) {
    showReaction(clean(source), clean(actionLabel));
  };
  svg.setReactionForAction = function (actionLabel, basePath) {
    var label = clean(actionLabel);
    if (!label) return clearReaction();
    var root = clean(basePath) || '../reactions/';
    showReaction(root.replace(/\/?$/, '/') + slugify(label) + '.svg', label);
  };
  svg.clearReaction = clearReaction;
}());
